flowchart TB
  Start["Ticket: distributed training<br/>is slow or stalling"] --> S0{"Step 0<br/>InfiniBand port state<br/>and counters"}
  S0 -->|"Initializing"| F0A["Subnet manager<br/>not running"]
  S0 -->|"error counters above 0"| F0B["Dirty optics<br/>or damaged fiber"]
  S0 -->|"Active, no errors"| S1{"Step 1<br/>intra-node bandwidth"}
  S1 -->|"25 to 30 GB/s"| F1["PCIe link down-trained"]
  S1 -->|"50 to 60 GB/s"| S2{"Step 2<br/>raw RDMA bandwidth"}
  S2 -->|"about half of line rate"| F2["Degraded lane or<br/>RoCE PFC / ECN loss"]
  S2 -->|"about line rate"| S3{"Step 3<br/>NCCL transport"}
  S3 -->|"NET/Socket"| F3A["TCP socket fallback"]
  S3 -->|"NET/IB without GDR"| F3B["Host bounce buffer"]
  S3 -->|"NVLink + GPUDirect RDMA"| S4{"Step 4<br/>application profile"}
  S4 -->|"many tiny AllReduces"| F4["Small-message latency"]

flowchart TB
  Call["Host calls cudaMemcpyAsync(d_dst, h_src, 268435456, H2D, stream)"] --> Check{"Is h_src page-locked (pinned)?<br/>(cudaHostAlloc / pin_memory=True)"}

  Check -->|"No: Pageable Host Memory"| Stage["Hidden CPU copy to internal pinned buffer<br/>Reference run (256 MiB): 74.318 ms (3.61 GB/s)<br/>Blocks host & serializes streams"]

  Check -->|"Yes: Pinned Host Memory"| NUMA{"Allocated on GPU's<br/>local NUMA socket?"}
  NUMA -->|"No: Remote NUMA Socket"| Remote["DMA crosses CPU UPI/xGMI link<br/>~1.75x penalty (~9.08 GB/s)"]
  NUMA -->|"Yes: Local NUMA Socket"| Local["Direct DMA over local PCIe root<br/>Reference run (256 MiB): 16.902 ms (15.88 GB/s = 4.40x)<br/>True H2D + Compute + D2H overlap"]

flowchart TB
  Start["Profile Kernel in Nsight Compute (ncu)<br/>Inspect DRAM BW %, Compute %, SM Active %, Stalls"] --> R1{"1. Are BOTH DRAM BW % and Compute % low<br/>with low SM Active % or No Eligible?"}
  R1 -->|"Yes"| Under["Regime 1: UNDERUTILIZED<br/>Not enough blocks/threads to fill all SMs<br/>Fix: Increase grid/batch size, CUDA Streams/Graphs"]
  R1 -->|"No (SMs have resident work)"| R2{"2. Is DRAM BW % near peak (>= 75%-80%)<br/>while Compute % is low?"}

  R2 -->|"Yes"| Mem["Regime 2: MEMORY BOUND<br/>Saturating HBM bandwidth; ALUs starved<br/>Fix: Shared-memory tiling, fusion, coalescing, FP8/FP4"]
  R2 -->|"No (DRAM BW % below peak)"| R3{"3. Are Compute / Tensor Core pipes<br/>near peak (>= 75%-80%)?"}

  R3 -->|"No (Eligible Warps/Cycle < 4 Schedulers)"| Lat["Regime 3: LATENCY BOUND<br/>Stalls on Scoreboard or Exec Dependency<br/>Fix: Raise Occupancy (50%-75%), 2-4x ILP, TMA prefetch"]
  R3 -->|"Yes (Math Pipe Throttle / Compute Busy)"| Comp["Regime 4: COMPUTE BOUND<br/>ALUs / Tensor Cores saturated<br/>Fix: FP16/FP8/NVFP4 Tensor Cores (tcgen05.mma), 2:4 sparsity"]
